INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6994196f-8d3c-4b7f-a609-4c26f0acc649', 'a1a1a1a1-3030-4000-8000-000000000001', 23, 'Dia 23 — Missão', 'Semana 4: Integrar', '{"pch": "Ide e fazei disc\u00edpulos\u2026 Sua vida \u00e9 sua maior mensagem.", "verse": "Mt 28,19", "lectio": "Leia Mt 28,16-20. A grande comiss\u00e3o.", "practice": "Escreva sua declara\u00e7\u00e3o de miss\u00e3o pessoal em 1 frase.", "question": "Se sua vida fosse uma mensagem, qual seria?"}'), ('b359357b-7017-498f-b4a5-ed558f7e910c', 'a1a1a1a1-3030-4000-8000-000000000001', 24, 'Dia 24 — Confiança', 'Semana 4: Integrar', '{"pch": "Confia no Senhor de todo o cora\u00e7\u00e3o\u2026 e Ele endireitar\u00e1 as tuas veredas.", "verse": "Pv 3,5-6", "lectio": "Leia Pv 3,1-8. Sabedoria vs. entendimento pr\u00f3prio.", "practice": "Entregue em ora\u00e7\u00e3o a \u00e1rea mais dif\u00edcil da sua vida.", "question": "Em que \u00e1rea voc\u00ea ainda n\u00e3o confiou a Deus?"}'), ('eed9da3a-776e-4f1d-a458-c9d651b640ca', 'a1a1a1a1-3030-4000-8000-000000000001', 25, 'Dia 25 — Perseverança', 'Semana 4: Integrar', '{"pch": "N\u00e3o nos cansemos de fazer o bem\u2026 porque a seu tempo colheremos. O prop\u00f3sito exige const\u00e2ncia.", "verse": "Gl 6,9", "lectio": "Leia Gl 6,7-10. A lei da semeadura.", "practice": "Retome algo que abandonou. D\u00ea mais um passo.", "question": "Em que voc\u00ea j\u00e1 desistiu cedo demais?"}'), ('abc5e0a3-7d65-4411-92c6-1bcd1dbadc5c', 'a1a1a1a1-3030-4000-8000-000000000001', 26, 'Dia 26 — Comunidade', 'Semana 4: Integrar', '{"pch": "Melhor \u00e9 serem dois do que um\u2026 Prop\u00f3sito isolado definha. Prop\u00f3sito compartilhado floresce.", "verse": "Ec 4,9-10", "lectio": "Leia Ec 4,9-12. A corda de tr\u00eas dobras.", "practice": "Convide algu\u00e9m para compartilhar sua jornada espiritual.", "question": "Quem caminha com voc\u00ea? Quem deveria caminhar?"}'), ('30bfc644-7672-461d-9694-0a1b3b0f00a1', 'a1a1a1a1-3030-4000-8000-000000000001', 27, 'Dia 27 — Legado', 'Semana 4: Integrar', '{"pch": "Combati o bom combate\u2026 completei a carreira. O que ficar\u00e1 quando voc\u00ea partir?", "verse": "2Tm 4,7", "lectio": "Leia 2Tm 4,6-8. Paulo olha para tr\u00e1s com paz.", "practice": "Escreva o que voc\u00ea quer que digam no seu funeral.", "question": "Que legado voc\u00ea quer deixar?"}'), ('4368c10d-fe86-468f-a43d-da8518d4ad35', 'a1a1a1a1-3030-4000-8000-000000000001', 28, 'Dia 28 — Gratidão', 'Semana 4: Integrar', '{"pch": "Em tudo dai gra\u00e7as\u2026 A gratid\u00e3o transforma a perspectiva e revela o prop\u00f3sito no cotidiano.", "verse": "1Ts 5,18", "lectio": "Leia 1Ts 5,16-24. Alegria, ora\u00e7\u00e3o e gratid\u00e3o.", "practice": "Escreva 10 motivos de gratid\u00e3o. Releia antes de dormir.", "question": "Pelo que voc\u00ea \u00e9 grato que nunca agradeceu?"}'), ('41a28ae5-52b9-407c-90d7-0a03b73b4a2a', 'a1a1a1a1-3030-4000-8000-000000000001', 29, 'Dia 29 — Compromisso', 'Semana 4: Integrar', '{"pch": "Ofere\u00e7am os seus corpos como sacrif\u00edcio vivo\u2026 Prop\u00f3sito sem compromisso \u00e9 fantasia.", "verse": "Rm 12,1", "lectio": "Leia Rm 12,1-2. Culto racional.", "practice": "Escreva 3 compromissos concretos para os pr\u00f3ximos 30 dias.", "question": "Com o que voc\u00ea se compromete a partir de hoje?"}'), ('0443b9b4-2ce3-415a-a730-2773c02f45c3', 'a1a1a1a1-3030-4000-8000-000000000001', 30, 'Dia 30 — Envio', 'Semana 4: Integrar', '{"pch": "Eis-me aqui, envia-me! Voc\u00ea n\u00e3o chegou ao fim\u2026 chegou ao come\u00e7o do que nasceu para viver.", "verse": "Is 6,8", "lectio": "Leia Is 6,1-8. A vis\u00e3o, a purifica\u00e7\u00e3o, o envio.", "practice": "Releia todas as suas reflex\u00f5es. Escreva uma carta para o seu eu de 30 dias atr\u00e1s.", "question": "Quem voc\u00ea se tornou nesses 30 dias?"}'), ('95b1090e-117c-4fd8-95ab-7b18071641cd', 'a1b2c3d4-0001-4000-8000-000000000001', 1, 'O Amor de Deus por Você', 'Descobrindo que somos amados', '{"bible_ref": "Jo 3,16", "reflection": "Deus nos amou primeiro. Medite sobre o que significa ser amado incondicionalmente."}'), ('e6c6deb4-e34a-429d-b30b-b65a615964eb', 'a1b2c3d4-0001-4000-8000-000000000001', 2, 'Primeira Oração', 'Aprendendo a conversar com Deus', '{"prayer": "Pai nosso", "instruction": "Reze lentamente, saboreando cada palavra."}'), ('65a76c6b-c1a8-46a3-907d-01704c71580b', 'a1b2c3d4-0001-4000-8000-000000000001', 3, 'A Palavra que Transforma', 'Introdução à Bíblia', '{"bible_ref": "Sl 119,105", "reflection": "A Palavra de Deus \u00e9 l\u00e2mpada para nossos passos."}'), ('8a7d7d4c-d0ca-400c-9da2-442febc6deaa', 'a1b2c3d4-0001-4000-8000-000000000001', 4, 'Exame de Consciência', 'Olhar para dentro com honestidade', '{"prompt": "O que mais me afasta de Deus no meu dia a dia?", "guidance": "Seja honesto consigo mesmo, sem julgamento."}'), ('38db9dd6-8288-4cb7-8ec2-1581cf639997', 'a1b2c3d4-0001-4000-8000-000000000001', 5, 'Os Sacramentos', 'Fontes de graça', '{"reflection": "Os sacramentos s\u00e3o sinais eficazes da gra\u00e7a divina.", "catechism_ref": "CIC 1210"}'), ('bfd8ee6c-4069-42a9-85ec-f5558311d60f', 'a1b2c3d4-0003-4000-8000-000000000003', 1, 'O Chamado à Contemplação', 'São João da Cruz', '{"text": "A alma que deseja alcan\u00e7ar a perfei\u00e7\u00e3o deve primeiro passar pela noite escura dos sentidos.", "source": "S\u00e3o Jo\u00e3o da Cruz"}'), ('7022626f-dd2e-4568-91b1-4eeccfc1b688', 'a1b2c3d4-0003-4000-8000-000000000003', 2, 'Oração de Quietude', 'Santa Teresa de Ávila', '{"instruction": "Feche os olhos, aquiete a mente e simplesmente esteja na presen\u00e7a de Deus por 20 minutos."}'), ('13e35790-a1aa-4ac7-bd61-6bdf6572b923', 'a1b2c3d4-0003-4000-8000-000000000003', 3, 'Lectio Divina Profunda', 'A Palavra que penetra a alma', '{"method": "Leia, medite, ore, contemple. Repita at\u00e9 sentir a Palavra falar ao seu cora\u00e7\u00e3o.", "bible_ref": "Jo 15,1-8"}'), ('d596428b-8081-4845-b0f1-581e8b574516', 'a1b2c3d4-0003-4000-8000-000000000003', 4, 'Diário Místico', 'Registre suas moções interiores', '{"prompt": "O que o Esp\u00edrito Santo est\u00e1 falando ao seu cora\u00e7\u00e3o? Que movimentos interiores voc\u00ea percebe?"}'), ('1e36c32b-9c60-4665-a21b-89eba8bdab35', 'a1b2c3d4-0003-4000-8000-000000000003', 5, 'A União com Deus', 'O fim da jornada é o começo', '{"text": "O importante n\u00e3o \u00e9 pensar muito, mas amar muito.", "source": "Santa Teresa de \u00c1vila", "catechism_ref": "CIC 2709"}'), ('b1b2c3d4-0001-4000-8000-000000000001', 'a1b2c3d4-0004-4000-8000-000000000004', 1, 'O Reconhecimento', 'Olhar para dentro com coragem', '{"intro": "Toda liberta\u00e7\u00e3o come\u00e7a com um ato de coragem: reconhecer que algo nos prende. N\u00e3o se trata de fraqueza \u2014 \u00e9 a mais profunda honestidade diante de Deus. Santo Agostinho escreveu: \"Fizeste-nos para Ti, Senhor, e o nosso cora\u00e7\u00e3o est\u00e1 inquieto enquanto n\u00e3o repousar em Ti.\" Essa inquieta\u00e7\u00e3o \u00e9 o primeiro sinal de que h\u00e1 correntes a serem rompidas.\n\nHoje, voc\u00ea \u00e9 convidado a parar. N\u00e3o para se julgar, mas para se ver. Como quem olha no espelho pela primeira vez sem desviar o olhar. O que te prende? Medo? Ressentimento? V\u00edcios? Padr\u00f5es que se repetem? Nomeie, sem vergonha. Deus j\u00e1 sabe \u2014 Ele espera que voc\u00ea tamb\u00e9m saiba.", "prayer": "Senhor, d\u00e1-me a coragem de olhar para dentro sem fugir. Mostra-me as correntes que eu mesmo n\u00e3o enxergo. N\u00e3o quero viver mais na superf\u00edcie \u2014 quero a verdade que liberta. Am\u00e9m.", "practice": "Encontre um lugar silencioso. Feche os olhos por 5 minutos e pe\u00e7a a Deus que ilumine uma \u00e1rea da sua vida onde voc\u00ea n\u00e3o \u00e9 livre. N\u00e3o force \u2014 apenas escute. Depois, escreva no seu di\u00e1rio o que veio ao cora\u00e7\u00e3o.", "scripture": "\"Conhecereis a verdade, e a verdade vos libertar\u00e1.\" \u2014 Jo 8,32\n\n\"Sonda-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o; prova-me e conhece os meus pensamentos.\" \u2014 Sl 139,23", "reflection": "1. Que padr\u00f5es se repetem na sua vida e te causam sofrimento?\n2. H\u00e1 algo que voc\u00ea evita olhar de frente? O que seria?\n3. Se Deus pudesse te dizer uma verdade agora, o que voc\u00ea acha que Ele diria?", "journal_prompt": "O que eu reconhe\u00e7o hoje que me prende? Qual \u00e9 a primeira corrente que consigo nomear?"}'), ('b1b2c3d4-0002-4000-8000-000000000002', 'a1b2c3d4-0004-4000-8000-000000000004', 2, 'As Correntes Invisíveis', 'Identificando o que nos aprisiona', '{"intro": "Existem pris\u00f5es com grades de ferro \u2014 e existem pris\u00f5es feitas de pensamentos, h\u00e1bitos e feridas. As mais perigosas s\u00e3o as que n\u00e3o vemos. S\u00e3o as narrativas que repetimos sobre n\u00f3s mesmos: \"eu n\u00e3o mere\u00e7o\", \"sempre ser\u00e1 assim\", \"Deus n\u00e3o se importa comigo\".\n\nS\u00e3o Tom\u00e1s de Aquino ensina que o pecado obscurece a raz\u00e3o e enfraquece a vontade. Mas n\u00e3o apenas o pecado nos prende: o medo, a vergonha, o orgulho, a autossufici\u00eancia \u2014 tudo isso cria correntes invis\u00edveis.\n\nHoje, vamos mapear essas correntes. N\u00e3o para nos condenar, mas para trazer \u00e0 luz o que vive na escurid\u00e3o.", "prayer": "Esp\u00edrito Santo, ilumina os cantos escuros da minha alma. Mostra-me as mentiras em que acreditei. Substitui cada corrente pela Tua verdade. Eu quero ser livre \u2014 verdadeiramente livre. Am\u00e9m.", "practice": "Pegue uma folha de papel e divida em duas colunas: \"O que eu acredito sobre mim\" e \"O que Deus diz sobre mim\". Preencha com honestidade. Compare as duas colunas e perceba onde est\u00e3o as distor\u00e7\u00f5es.", "scripture": "\"Onde est\u00e1 o Esp\u00edrito do Senhor, a\u00ed h\u00e1 liberdade.\" \u2014 2Cor 3,17\n\n\"N\u00e3o vos conformeis com este mundo, mas transformai-vos pela renova\u00e7\u00e3o da vossa mente.\" \u2014 Rm 12,2", "reflection": "1. Que mentiras voc\u00ea acredita sobre si mesmo h\u00e1 anos?\n2. Existe algum medo que controla suas decis\u00f5es?\n3. H\u00e1 algum relacionamento ou situa\u00e7\u00e3o que te mant\u00e9m preso(a) a um padr\u00e3o destrutivo?", "journal_prompt": "Quais s\u00e3o as mentiras que descobri que acreditava sobre mim? Como elas afetaram minhas escolhas?"}'), ('b1b2c3d4-0003-4000-8000-000000000003', 'a1b2c3d4-0004-4000-8000-000000000004', 3, 'O Espelho da Alma', 'Enfrentando a verdade sobre quem somos', '{"intro": "O exame de consci\u00eancia \u00e9 a pr\u00e1tica mais antiga e poderosa da vida crist\u00e3. Santo In\u00e1cio de Loyola o considerava mais importante que a pr\u00f3pria ora\u00e7\u00e3o \u2014 porque sem verdade, a ora\u00e7\u00e3o se torna fuga.\n\nHoje, vamos fazer algo radical: olhar para a alma como se olh\u00e1ssemos num espelho sem filtros. N\u00e3o \u00e9 autocondena\u00e7\u00e3o \u2014 \u00e9 autoconsci\u00eancia na presen\u00e7a de Deus. Como diz Santa Teresa de \u00c1vila: \"O autoconhecimento \u00e9 a porta da ora\u00e7\u00e3o.\"", "prayer": "Jesus manso e humilde de cora\u00e7\u00e3o, fazei o meu cora\u00e7\u00e3o semelhante ao Vosso. N\u00e3o me deixes fugir da verdade. D\u00e1-me a gra\u00e7a de me ver como Tu me v\u00eas \u2014 com amor e com verdade. Am\u00e9m.", "practice": "Fa\u00e7a o Exame de Consci\u00eancia de Santo In\u00e1cio: 1) Agrade\u00e7a as gra\u00e7as do dia. 2) Pe\u00e7a luz para ver seus atos. 3) Reveja as \u00faltimas 24 horas. 4) Pe\u00e7a perd\u00e3o pelo que errou. 5) Proponha-se a melhorar amanh\u00e3.", "scripture": "\"Examina-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o. Prova-me e conhece os meus pensamentos ansiosos. V\u00ea se h\u00e1 em mim algum caminho mau e guia-me pelo caminho eterno.\" \u2014 Sl 139,23-24", "reflection": "1. Se algu\u00e9m filmasse sua vida interior por uma semana, o que veria?\n2. Qual \u00e9 o pecado que voc\u00ea mais justifica para si mesmo?\n3. H\u00e1 algo que voc\u00ea nunca confessou \u2014 n\u00e3o por esquecimento, mas por vergonha?", "journal_prompt": "O que o espelho da alma me mostrou hoje? O que preciso levar ao sacramento da confiss\u00e3o?"}'), ('b1b2c3d4-0004-4000-8000-000000000004', 'a1b2c3d4-0004-4000-8000-000000000004', 4, 'A Porta Estreita', 'O caminho da renúncia e da entrega', '{"intro": "\"Entrai pela porta estreita\" \u2014 esta palavra de Jesus n\u00e3o \u00e9 um convite ao sofrimento gratuito, mas \u00e0 escolha consciente. A porta larga \u00e9 a comodidade, o \"deixa pra l\u00e1\", o conformismo espiritual. A porta estreita \u00e9 a decis\u00e3o de morrer para si mesmo.\n\nS\u00e3o Jo\u00e3o da Cruz chamou isso de \"noite escura da alma\" \u2014 o momento em que Deus nos convida a soltar o que nos d\u00e1 falsa seguran\u00e7a para encontrar a verdadeira. \u00c9 doloroso. Mas \u00e9 o \u00fanico caminho para a liberdade.", "prayer": "Senhor Jesus, Tu passaste pela porta estreita da Cruz por amor a mim. D\u00e1-me a coragem de fazer o mesmo. N\u00e3o quero a comodidade que me afasta de Ti. Quero a estreiteza que me aproxima. Am\u00e9m.", "practice": "Escolha uma ren\u00fancia concreta para esta semana. Pode ser algo pequeno: um v\u00edcio digital, uma comodidade, um padr\u00e3o de consumo. Ofere\u00e7a essa ren\u00fancia a Deus como sacrif\u00edcio de amor. Registre como se sente ao longo dos dias.", "scripture": "\"Entrai pela porta estreita, pois larga \u00e9 a porta e espa\u00e7oso o caminho que conduz \u00e0 perdi\u00e7\u00e3o, e muitos s\u00e3o os que entram por ela.\" \u2014 Mt 7,13\n\n\"Se algu\u00e9m quiser vir ap\u00f3s mim, negue-se a si mesmo, tome a sua cruz e siga-me.\" \u2014 Mt 16,24", "reflection": "1. O que voc\u00ea mais tem medo de perder? Essa coisa tem poder sobre voc\u00ea?\n2. Que conforto ou h\u00e1bito Deus est\u00e1 te pedindo para soltar?\n3. O que significa \"morrer para si mesmo\" na sua vida concreta?", "journal_prompt": "Qual ren\u00fancia escolhi para esta semana? O que sinto ao pensar em abrir m\u00e3o disso?"}'), ('b1b2c3d4-0005-4000-8000-000000000005', 'a1b2c3d4-0004-4000-8000-000000000004', 5, 'O Perdão Radical', 'Quebrando a maior corrente de todas', '{"intro": "Se h\u00e1 uma corrente que prende mais almas do que qualquer outra, \u00e9 a falta de perd\u00e3o. O ressentimento \u00e9 um veneno que bebemos esperando que o outro morra. E no entanto, quantos de n\u00f3s carregamos m\u00e1goas de anos \u2014 contra pais, amigos, ex-parceiros, contra n\u00f3s mesmos, e at\u00e9 contra Deus?\n\nJesus n\u00e3o sugeriu o perd\u00e3o \u2014 Ele o ordenou. E n\u00e3o uma vez, mas setenta vezes sete. Porque o perd\u00e3o n\u00e3o \u00e9 um sentimento: \u00e9 uma decis\u00e3o da vontade, sustentada pela gra\u00e7a. Hoje, vamos enfrentar a maior corrente.", "prayer": "Pai misericordioso, Tu que perdoaste a humanidade inteira do alto da Cruz, d\u00e1-me a gra\u00e7a de perdoar quem me feriu. Cura as feridas que carrego. Liberta-me do peso do ressentimento. Eu escolho perdoar \u2014 n\u00e3o porque seja f\u00e1cil, mas porque Tu me pedes. Am\u00e9m.", "practice": "Escreva uma carta de perd\u00e3o (que n\u00e3o precisa ser enviada). Dirija-se \u00e0 pessoa que te feriu. Descreva a dor, reconhe\u00e7a a ferida, e ent\u00e3o escreva as palavras: \"Eu escolho te perdoar. Entrego esta dor a Deus.\" Depois, reze um Pai-Nosso lentamente, detendo-se em \"perdoai as nossas ofensas assim como n\u00f3s perdoamos a quem nos tem ofendido.\"", "scripture": "\"Se perdoardes aos homens as suas ofensas, vosso Pai celeste tamb\u00e9m vos perdoar\u00e1.\" \u2014 Mt 6,14\n\n\"Pai, perdoa-lhes, porque n\u00e3o sabem o que fazem.\" \u2014 Lc 23,34", "reflection": "1. Quem voc\u00ea ainda n\u00e3o perdoou de verdade?\n2. Voc\u00ea se perdoou pelos seus pr\u00f3prios erros?\n3. H\u00e1 alguma m\u00e1goa contra Deus \u2014 por algo que Ele permitiu acontecer?", "journal_prompt": "Quem eu perdoei hoje? Como me senti ao escrever a carta de perd\u00e3o? O que mudou dentro de mim?"}'), ('b1b2c3d4-0006-4000-8000-000000000006', 'a1b2c3d4-0004-4000-8000-000000000004', 6, 'A Liberdade dos Filhos', 'Vivendo como quem foi libertado', '{"intro": "Voc\u00ea chegou ao fim desta jornada \u2014 mas na verdade, este \u00e9 o come\u00e7o. A liberdade que Cristo oferece n\u00e3o \u00e9 aus\u00eancia de dificuldades: \u00e9 a presen\u00e7a de Deus em cada uma delas. Como diz S\u00e3o Paulo: \"Para a liberdade \u00e9 que Cristo nos libertou. Permanecei firmes e n\u00e3o vos submetais de novo ao jugo da escravid\u00e3o.\"\n\nAgora que voc\u00ea reconheceu suas correntes, olhou de frente para a verdade, passou pela porta estreita e perdoou \u2014 \u00e9 hora de viver como filho(a) livre. N\u00e3o como escravo do medo, da culpa ou do passado. Mas como herdeiro(a) do Reino.", "prayer": "Senhor Jesus Cristo, Libertador da minha alma, obrigado(a) por esta jornada. Obrigado(a) por me mostrar a verdade, mesmo quando doeu. Obrigado(a) por romper as correntes que me prendiam. Eu me comprometo a viver na liberdade que Tu me deste. N\u00e3o voltarei atr\u00e1s. Am\u00e9m.", "practice": "Crie um \"plano de liberdade\": 1) Uma pr\u00e1tica di\u00e1ria de ora\u00e7\u00e3o (5 min). 2) Um exame de consci\u00eancia semanal. 3) Confiss\u00e3o mensal. 4) Uma pessoa de confian\u00e7a para prestar contas. Comprometa-se com este plano por 30 dias.", "scripture": "\"Para a liberdade \u00e9 que Cristo nos libertou. Permanecei firmes e n\u00e3o vos submetais de novo ao jugo da escravid\u00e3o.\" \u2014 Gl 5,1\n\n\"Se o Filho vos libertar, verdadeiramente sereis livres.\" \u2014 Jo 8,36", "reflection": "1. O que mudou em voc\u00ea desde o in\u00edcio desta jornada?\n2. Quais correntes foram rompidas? Quais ainda precisam de trabalho?\n3. Como voc\u00ea vai manter essa liberdade no dia a dia?", "journal_prompt": "O que esta jornada significou para mim? Qual \u00e9 meu compromisso a partir de agora? Que palavras eu diria a algu\u00e9m que est\u00e1 come\u00e7ando onde eu comecei?"}'), ('8197c079-be7b-4fe0-b6b6-52fca2c2ad2d', 'a1b2c3d4-1111-4000-8000-000000000001', 1, 'O Despertar Interior', 'Por que uma rotina espiritual?', '{"intro": "Antes de tudo, precisamos entender: uma rotina espiritual n\u00e3o \u00e9 uma pris\u00e3o de hor\u00e1rios \u2014 \u00e9 uma estrutura que liberta. Assim como um rio precisa de margens para fluir com for\u00e7a, nossa vida espiritual precisa de ritmo para crescer. Santo In\u00e1cio de Loyola dizia que a ordem do dia \u00e9 a primeira vit\u00f3ria contra o caos interior. Quando estabelecemos momentos fixos de encontro com Deus, deixamos de depender da emo\u00e7\u00e3o e passamos a viver pela decis\u00e3o.", "prayer": "Senhor, ensina-me a Te buscar n\u00e3o quando sobra tempo, mas como a primeira coisa do meu dia. Que eu aprenda a construir minha vida sobre o alicerce da Tua presen\u00e7a. Am\u00e9m.", "practice": "Escolha dois hor\u00e1rios fixos hoje \u2014 manh\u00e3 e noite \u2014 e reserve pelo menos 5 minutos em cada para sil\u00eancio e ora\u00e7\u00e3o.", "scripture": "\"Buscai primeiro o Reino de Deus e a sua justi\u00e7a, e todas estas coisas vos ser\u00e3o acrescentadas.\" \u2014 Mt 6,33", "reflection": "Em que momentos do seu dia voc\u00ea sente que Deus est\u00e1 mais distante? Que horas seriam ideais para reservar um encontro di\u00e1rio com Ele?"}'), ('6df20be7-3248-4db0-88cb-13265ffc745b', 'a1b2c3d4-1111-4000-8000-000000000001', 2, 'Oração da Manhã', 'Começando o dia com Deus', '{"intro": "A tradi\u00e7\u00e3o crist\u00e3 sempre valorizou a ora\u00e7\u00e3o matutina. Os monges beneditinos iniciam o dia com as Laudes antes do sol nascer. Por qu\u00ea? Porque oferecer as prim\u00edcias do dia a Deus \u00e9 reconhecer que tudo vem Dele. Uma ora\u00e7\u00e3o matinal simples \u2014 mesmo de 5 minutos \u2014 transforma a qualidade do seu dia inteiro. N\u00e3o precisa ser longa; precisa ser sincera.", "prayer": "Deus de toda gra\u00e7a, que as primeiras palavras da minha boca sejam de louvor. Que eu aprenda com Jesus a buscar-Te antes de tudo. Am\u00e9m.", "practice": "Amanh\u00e3, ao despertar, antes de olhar o celular, fa\u00e7a esta ora\u00e7\u00e3o: Pai, entrego este dia nas Tuas m\u00e3os. Guia meus passos, meus pensamentos e minhas palavras.", "scripture": "\"De manh\u00e3, por\u00e9m, tendo-se levantado muito cedo, saiu e foi a um lugar deserto, e ali orava.\" \u2014 Mc 1,35", "reflection": "Como voc\u00ea normalmente come\u00e7a seu dia? O que mudaria se os primeiros 5 minutos fossem dedicados a Deus?"}'), ('bfe0188e-4821-488d-8502-86fa2e397217', 'a1b2c3d4-1111-4000-8000-000000000001', 3, 'Lectio Divina Diária', 'Alimentando-se da Palavra', '{"intro": "A Lectio Divina \u00e9 um m\u00e9todo milenar de leitura orante da B\u00edblia. Diferente do estudo acad\u00eamico, ela busca o encontro pessoal com Deus atrav\u00e9s do texto sagrado. S\u00e3o quatro passos: Leitura (lectio), Medita\u00e7\u00e3o (meditatio), Ora\u00e7\u00e3o (oratio) e Contempla\u00e7\u00e3o (contemplatio). Mesmo 10 minutos por dia com este m\u00e9todo podem revolucionar sua rela\u00e7\u00e3o com a Escritura.", "prayer": "Esp\u00edrito Santo, abre meus olhos para ver as maravilhas da Tua lei. Que a Tua Palavra n\u00e3o seja apenas texto, mas vida para minha alma. Am\u00e9m.", "practice": "Escolha um Evangelho (sugerimos Marcos, o mais curto). Leia apenas um par\u00e1grafo por dia usando os 4 passos da Lectio Divina. Anote uma frase que tocou seu cora\u00e7\u00e3o.", "scripture": "\"L\u00e2mpada para os meus p\u00e9s \u00e9 a tua palavra, e luz para o meu caminho.\" \u2014 Sl 119,105", "reflection": "Qual foi a \u00faltima vez que uma passagem b\u00edblica realmente tocou seu cora\u00e7\u00e3o? O que aconteceria se voc\u00ea fizesse isso diariamente?"}'), ('9f4f5035-2c4d-4b3b-9464-3406780937d7', 'a1b2c3d4-1111-4000-8000-000000000001', 4, 'O Exame de Consciência', 'Olhando o dia com os olhos de Deus', '{"intro": "O Exame de Consci\u00eancia, popularizado por Santo In\u00e1cio, \u00e9 uma ora\u00e7\u00e3o noturna poderosa. Em 5 passos simples, voc\u00ea revisa o dia com gratid\u00e3o, reconhece as mo\u00e7\u00f5es interiores, identifica onde falhou e planeja o amanh\u00e3. N\u00e3o \u00e9 uma sess\u00e3o de culpa \u2014 \u00e9 um momento de honestidade amorosa diante de Deus. Muitos santos consideravam esta a ora\u00e7\u00e3o mais importante do dia.", "prayer": "Senhor, ajuda-me a ver meu dia com Teus olhos. Onde falhei, d\u00e1-me Teu perd\u00e3o. Onde acertei, d\u00e1-me Tua humildade. Am\u00e9m.", "practice": "Hoje \u00e0 noite, fa\u00e7a o Exame em 5 passos: 1) Agrade\u00e7a; 2) Pe\u00e7a luz ao Esp\u00edrito; 3) Reveja o dia; 4) Pe\u00e7a perd\u00e3o; 5) Planeje o amanh\u00e3 com Deus.", "scripture": "\"Examina-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o; prova-me e conhece os meus pensamentos.\" \u2014 Sl 139,23", "reflection": "No final do dia, como voc\u00ea se sente? Consegue identificar momentos em que Deus agiu na sua vida hoje?"}'), ('635e9a5e-6ba8-4189-ad69-2cdceb7f330a', 'a1b2c3d4-1111-4000-8000-000000000001', 5, 'Jejum e Silêncio', 'Esvaziando para ser preenchido', '{"intro": "O jejum n\u00e3o \u00e9 apenas abstin\u00eancia de comida \u2014 \u00e9 uma pr\u00e1tica de esvaziamento que abre espa\u00e7o para Deus. Jesus jejuou 40 dias no deserto antes de iniciar seu minist\u00e9rio. O sil\u00eancio interior, por sua vez, \u00e9 o terreno f\u00e9rtil onde a voz de Deus pode ser ouvida. Numa cultura de ru\u00eddo constante, aprender a silenciar \u00e9 um ato revolucion\u00e1rio de f\u00e9.", "prayer": "Deus do sil\u00eancio, ensina-me a esvaziar-me para ser preenchido por Ti. Que eu encontre no vazio a Tua plenitude. Am\u00e9m.", "practice": "Escolha um jejum para esta semana: redes sociais por 1 dia, ou sil\u00eancio de 30 minutos (sem m\u00fasica, sem podcast, sem conversa). Observe o que acontece no seu interior.", "scripture": "\"Mas tu, quando jejuares, unge a cabe\u00e7a e lava o rosto, para que n\u00e3o pare\u00e7as aos homens que jejuas.\" \u2014 Mt 6,17-18", "reflection": "De que forma o barulho (externo e interno) dificulta seu encontro com Deus? O que voc\u00ea poderia \"jejuar\" al\u00e9m de comida?"}'), ('39047abc-687a-4ad8-91f5-f383049ef091', 'a1b2c3d4-1111-4000-8000-000000000001', 6, 'Perseverança na Rotina', 'Quando a motivação acaba, a disciplina começa', '{"intro": "A maior tenta\u00e7\u00e3o da vida espiritual n\u00e3o \u00e9 o pecado grave \u2014 \u00e9 a mediocridade. \u00c9 o dia em que voc\u00ea \"n\u00e3o est\u00e1 com vontade\". Santa Teresa de \u00c1vila confessou que, por anos, sua ora\u00e7\u00e3o era \u00e1rida e sem consola\u00e7\u00e3o. Mas ela perseverou. E foi nos desertos que encontrou as maiores gra\u00e7as. A rotina espiritual n\u00e3o depende de sentir \u2014 depende de decidir, todos os dias.", "prayer": "Senhor, quando a aridez vier, lembra-me que Tu est\u00e1s presente mesmo no sil\u00eancio. D\u00e1-me a gra\u00e7a da perseveran\u00e7a. Am\u00e9m.", "practice": "Escreva sua Regra de Vida pessoal: hor\u00e1rio de ora\u00e7\u00e3o, leitura b\u00edblica, exame de consci\u00eancia. Cole em um lugar vis\u00edvel. Comprometa-se por 21 dias.", "scripture": "\"Aquele que perseverar at\u00e9 o fim, esse ser\u00e1 salvo.\" \u2014 Mt 24,13", "reflection": "Qual \u00e9 sua maior dificuldade para manter uma rotina espiritual? O que te faria n\u00e3o desistir mesmo nos dias dif\u00edceis?"}'), ('e01f8f74-61fe-4d25-b27d-72112e86ecd4', 'a1b2c3d4-2222-4000-8000-000000000002', 1, 'O que é Oração?', 'Redescubrindo o diálogo com Deus', '{"intro": "Santa Teresa de \u00c1vila definiu ora\u00e7\u00e3o como \"um trato de amizade com Aquele que sabemos que nos ama\". N\u00e3o \u00e9 uma f\u00f3rmula m\u00e1gica nem uma lista de pedidos \u2014 \u00e9 um relacionamento. Assim como qualquer amizade, exige tempo, presen\u00e7a e sinceridade. O Catecismo ensina que ora\u00e7\u00e3o \u00e9 a eleva\u00e7\u00e3o da alma a Deus (CIC 2559). Mas antes de elevar, precisamos reconhecer: somos amados antes de orar.", "prayer": "Senhor, ensina-me a rezar. Que eu descubra que antes de eu Te procurar, Tu j\u00e1 me encontraste. Am\u00e9m.", "practice": "Reserve 10 minutos hoje para simplesmente estar na presen\u00e7a de Deus. Sem pedir nada. Sem dizer nada. Apenas estar.", "scripture": "\"Eis que estou \u00e0 porta e bato. Se algu\u00e9m ouvir a minha voz e abrir a porta, entrarei em sua casa e cearei com ele, e ele comigo.\" \u2014 Ap 3,20", "reflection": "Se ora\u00e7\u00e3o \u00e9 amizade, como est\u00e1 sua amizade com Deus hoje? Voc\u00ea fala mais ou escuta mais?"}'), ('9e816128-a358-40a7-ae0f-8063a050e04f', 'a1b2c3d4-2222-4000-8000-000000000002', 2, 'Oração Vocal', 'As palavras que nos unem ao céu', '{"intro": "A ora\u00e7\u00e3o vocal \u00e9 a forma mais acess\u00edvel de rezar. O Pai Nosso, a Ave Maria, o Gl\u00f3ria \u2014 s\u00e3o ora\u00e7\u00f5es que Jesus e a Igreja nos ensinaram. Mas aten\u00e7\u00e3o: rezar vocalmente n\u00e3o \u00e9 repetir palavras vazias. Jesus alertou contra a \"v\u00e3 repeti\u00e7\u00e3o\" (Mt 6,7). A chave \u00e9 unir l\u00e1bios e cora\u00e7\u00e3o. Santo Agostinho dizia: \"Quem canta, reza duas vezes\". A ora\u00e7\u00e3o vocal \u00e9 porta de entrada para profundidades maiores.", "prayer": "Pai nosso que est\u00e1s nos c\u00e9us... ensina-me a dizer estas palavras n\u00e3o com os l\u00e1bios apenas, mas com toda a minha alma. Am\u00e9m.", "practice": "Reze o Pai Nosso cinco vezes, mas muito devagar. A cada frase, pare e reflita sobre o que est\u00e1 dizendo. Anote qual frase mais tocou seu cora\u00e7\u00e3o.", "scripture": "\"V\u00f3s, pois, orai assim: Pai nosso, que est\u00e1s nos c\u00e9us, santificado seja o teu nome...\" \u2014 Mt 6,9", "reflection": "Qual ora\u00e7\u00e3o vocal voc\u00ea mais reza? Consegue rez\u00e1-la devagar, sentindo cada palavra?"}'), ('7fca0786-62cd-40f5-bdb5-ef6c0ddd152b', 'a1b2c3d4-2222-4000-8000-000000000002', 3, 'Oração Mental', 'O silêncio que transforma', '{"intro": "A ora\u00e7\u00e3o mental \u00e9 a conversa \u00edntima da alma com Deus \u2014 sem f\u00f3rmulas, sem textos decorados. \u00c9 o cora\u00e7\u00e3o que fala ao Cora\u00e7\u00e3o. Santa Teresa de Jesus dizia que muitos abandonam a ora\u00e7\u00e3o mental por acharem que n\u00e3o sabem fazer \u2014 mas basta \"olhar para Ele que nos olha\". A ora\u00e7\u00e3o mental n\u00e3o exige erudi\u00e7\u00e3o; exige humildade e desejo. Mesmo 5 minutos de ora\u00e7\u00e3o mental valem mais que horas de distra\u00e7\u00e3o.", "prayer": "Jesus manso e humilde de cora\u00e7\u00e3o, fazei o meu cora\u00e7\u00e3o semelhante ao Vosso. Ensina-me o sil\u00eancio que cura e transforma. Am\u00e9m.", "practice": "Sente-se em sil\u00eancio. Feche os olhos. Imagine Jesus sentado ao seu lado. Diga-Lhe o que est\u00e1 no seu cora\u00e7\u00e3o. Depois, fique em sil\u00eancio e escute. 10 minutos.", "scripture": "\"Mas tu, quando orares, entra no teu quarto, fecha a porta e ora a teu Pai em segredo; e teu Pai, que v\u00ea em segredo, te recompensar\u00e1.\" \u2014 Mt 6,6", "reflection": "Voc\u00ea j\u00e1 experimentou o sil\u00eancio interior na ora\u00e7\u00e3o? O que acontece quando voc\u00ea tenta ficar em sil\u00eancio diante de Deus?"}'), ('550f63c0-0129-410d-b548-e854e0b1ca80', 'a1b2c3d4-2222-4000-8000-000000000002', 4, 'O Rosário Contemplativo', 'Maria como mestra de oração', '{"intro": "O Ros\u00e1rio n\u00e3o \u00e9 mera repeti\u00e7\u00e3o \u2014 \u00e9 contempla\u00e7\u00e3o dos mist\u00e9rios de Cristo atrav\u00e9s dos olhos de Maria. S\u00e3o Jo\u00e3o Paulo II, em sua enc\u00edclica Rosarium Virginis Mariae, chamou o Ros\u00e1rio de \"comp\u00eandio do Evangelho\". Cada dezena \u00e9 uma janela para um momento da vida de Jesus. O segredo \u00e9 contemplar, n\u00e3o apenas contar. Quando rezado com o cora\u00e7\u00e3o, o Ros\u00e1rio se torna uma escola de ora\u00e7\u00e3o profunda.", "prayer": "Maria, minha M\u00e3e, ensina-me a contemplar teu Filho como tu o contemplavas. Que cada Ave-Maria seja um passo mais perto do Cora\u00e7\u00e3o de Jesus. Am\u00e9m.", "practice": "Reze uma dezena do Ros\u00e1rio (10 Ave-Marias) contemplando um mist\u00e9rio. Antes de come\u00e7ar, leia a passagem b\u00edblica correspondente. Imagine-se na cena.", "scripture": "\"Maria, por\u00e9m, guardava todas estas coisas, meditando-as no seu cora\u00e7\u00e3o.\" \u2014 Lc 2,19", "reflection": "Qual mist\u00e9rio do Ros\u00e1rio mais fala ao seu cora\u00e7\u00e3o hoje? Por que esse mist\u00e9rio te toca?"}'), ('bee9bcec-b493-48d8-bf5b-8ab8189fe025', 'a1b2c3d4-2222-4000-8000-000000000002', 5, 'Oração de Intercessão', 'Rezar pelos outros como Jesus reza por nós', '{"intro": "Jesus vive para interceder por n\u00f3s (Hb 7,25). Quando rezamos pelos outros, participamos da miss\u00e3o sacerdotal de Cristo. A intercess\u00e3o n\u00e3o \u00e9 informar Deus sobre problemas \u2014 Ele j\u00e1 sabe. \u00c9 unir nosso cora\u00e7\u00e3o ao Dele, carregando juntos o peso do mundo. Santos como Padre Pio recebiam milhares de inten\u00e7\u00f5es e as levavam ao altar. Cada intercess\u00e3o \u00e9 um ato de amor concreto.", "prayer": "Senhor, coloco diante de Ti todos aqueles que carrego no cora\u00e7\u00e3o. Cura, liberta, consola e transforma pela Tua miseric\u00f3rdia. Am\u00e9m.", "practice": "Fa\u00e7a uma lista de 5 pessoas que precisam de ora\u00e7\u00e3o. Reserve 2 minutos para cada uma. Apresente-as a Deus com amor, n\u00e3o com ansiedade.", "scripture": "\"Eu vos digo: Pedi e vos ser\u00e1 dado; buscai e achareis; batei e vos ser\u00e1 aberto.\" \u2014 Lc 11,9", "reflection": "Por quem voc\u00ea sente que Deus est\u00e1 pedindo que reze? H\u00e1 algu\u00e9m que precisa das suas ora\u00e7\u00f5es agora?"}'), ('fd5600a3-0646-49ae-b83c-b48815bd4835', 'a1b2c3d4-2222-4000-8000-000000000002', 6, 'Perseverança na Oração', 'Quando Deus parece silencioso', '{"intro": "Todo orante passa pelo deserto \u2014 a \"noite escura\" de S\u00e3o Jo\u00e3o da Cruz. S\u00e3o momentos em que Deus parece ausente, a ora\u00e7\u00e3o parece vazia e o cora\u00e7\u00e3o est\u00e1 seco. Mas \u00e9 justamente a\u00ed que a f\u00e9 se purifica. Madre Teresa de Calcut\u00e1 viveu 50 anos de aridez espiritual \u2014 e nunca deixou de rezar. A perseveran\u00e7a na ora\u00e7\u00e3o n\u00e3o \u00e9 hero\u00edsmo; \u00e9 confian\u00e7a de que Deus est\u00e1 trabalhando no escuro.", "prayer": "Deus fiel, mesmo quando n\u00e3o Te sinto, sei que est\u00e1s aqui. D\u00e1-me a gra\u00e7a de perseverar na ora\u00e7\u00e3o, confiando que Tu ages no sil\u00eancio. Am\u00e9m.", "practice": "Fa\u00e7a um compromisso escrito: \"Eu me comprometo a rezar todos os dias, por pelo menos 10 minutos, durante os pr\u00f3ximos 30 dias \u2014 mesmo quando n\u00e3o sentir vontade.\" Assine e date.", "scripture": "\"Vigia e ora, para que n\u00e3o entreis em tenta\u00e7\u00e3o. O esp\u00edrito est\u00e1 pronto, mas a carne \u00e9 fraca.\" \u2014 Mt 26,41", "reflection": "Voc\u00ea j\u00e1 passou por per\u00edodos de aridez na ora\u00e7\u00e3o? Como reagiu? O que aprendeu com isso?"}'), ('c1c2c3d4-3301-4000-8000-000000000001', 'b1b2c3d4-3333-4000-8000-000000000003', 1, 'O que é Vocação?', 'Fundamentos do chamado divino', '{"text": "A voca\u00e7\u00e3o n\u00e3o \u00e9 apenas uma profiss\u00e3o ou estado de vida \u2014 \u00e9 o chamado \u00fanico e irrepet\u00edvel que Deus faz a cada pessoa. Santo Tom\u00e1s de Aquino ensina que Deus nos criou com um prop\u00f3sito espec\u00edfico, inscrito em nossa pr\u00f3pria natureza.\n\n\"Deus n\u00e3o nos chama porque somos bons; Ele nos torna bons porque nos chama.\" \u2014 S\u00e3o Jo\u00e3o Cris\u00f3stomo\n\nExistem quatro voca\u00e7\u00f5es fundamentais na Igreja:\n1. **Matrim\u00f4nio** \u2014 chamado \u00e0 santidade conjugal e familiar\n2. **Sacerd\u00f3cio** \u2014 chamado a servir como alter Christus\n3. **Vida Consagrada** \u2014 chamado \u00e0 radicalidade evang\u00e9lica\n4. **Vida Leiga** \u2014 chamado \u00e0 santifica\u00e7\u00e3o no mundo\n\nO discernimento come\u00e7a com a disposi\u00e7\u00e3o de dizer: \"Senhor, o que queres que eu fa\u00e7a?\" (At 9,6)", "scripture": "Jr 1,5 \u2014 Antes de te formar no ventre materno, eu te conheci; antes de sa\u00edres do seio, eu te consagrei."}'), ('c1c2c3d4-3302-4000-8000-000000000002', 'b1b2c3d4-3333-4000-8000-000000000003', 2, 'Oração de Entrega', 'Colocar-se diante de Deus', '{"text": "Senhor Jesus Cristo,\nV\u00f3s que me chamais pelo nome,\nque me conheceis antes de eu nascer,\nconcedei-me a gra\u00e7a de ouvir Vossa voz\nno sil\u00eancio do meu cora\u00e7\u00e3o.\n\nTirai de mim todo medo,\ntoda resist\u00eancia,\ntodo apego \u00e0 minha vontade pr\u00f3pria.\n\nQuero apenas o que V\u00f3s quereis para mim.\nFazei de mim instrumento d\u00f3cil\nnas Vossas m\u00e3os.\n\nMaria, M\u00e3e do discernimento,\nque disseste o \"sim\" perfeito,\nintercessora por mim nesta jornada.\n\nAm\u00e9m.", "instruction": "Reze esta ora\u00e7\u00e3o lentamente, em ambiente silencioso. Repita as partes que tocarem seu cora\u00e7\u00e3o."}'), ('c1c2c3d4-3303-4000-8000-000000000003', 'b1b2c3d4-3333-4000-8000-000000000003', 3, 'Sinais do Chamado', 'Como Deus fala conosco', '{"text": "Santo In\u00e1cio de Loyola, mestre do discernimento, ensina que Deus nos fala de diversas maneiras:\n\n**1. Consola\u00e7\u00e3o Espiritual**\nUm sentimento profundo de paz, alegria e atra\u00e7\u00e3o por determinado caminho. N\u00e3o \u00e9 euforia passageira, mas uma serenidade duradoura.\n\n**2. Desola\u00e7\u00e3o Espiritual**\nInquieta\u00e7\u00e3o, tristeza, confus\u00e3o \u2014 sinais de que algo n\u00e3o est\u00e1 alinhado com a vontade de Deus.\n\n**3. Mo\u00e7\u00f5es Interiores**\nDesejos persistentes que surgem na ora\u00e7\u00e3o e se confirmam com o tempo.\n\n**4. Sinais Exteriores**\nCircunst\u00e2ncias providenciais, conselhos de diretores espirituais, portas que se abrem ou fecham.\n\n\"Em tempo de desola\u00e7\u00e3o, nunca fazer mudan\u00e7a.\" \u2014 Santo In\u00e1cio\n\nO discernimento requer paci\u00eancia. Deus n\u00e3o tem pressa.", "scripture": "1Rs 19,11-13 \u2014 O Senhor n\u00e3o estava no vento, nem no terremoto, nem no fogo... mas na brisa suave."}'), ('c1c2c3d4-3304-4000-8000-000000000004', 'b1b2c3d4-3333-4000-8000-000000000003', 4, 'Reflexão: Minha História Vocacional', 'Olhar para trás para enxergar adiante', '{"text": "Reflita sobre sua hist\u00f3ria pessoal \u00e0 luz do chamado de Deus:\n\n1. **Quais momentos da minha vida me trouxeram maior paz e realiza\u00e7\u00e3o?**\n2. **Quando me senti mais pr\u00f3ximo de Deus?**\n3. **Que talentos e dons recebi que poderiam servir aos outros?**\n4. **H\u00e1 algum desejo persistente no meu cora\u00e7\u00e3o que nunca desaparece?**\n5. **O que as pessoas que me conhecem bem dizem sobre meus dons?**\n\nEscreva suas respostas no di\u00e1rio espiritual. N\u00e3o tenha pressa \u2014 o discernimento \u00e9 um processo.", "prompt": "Descreva um momento em que voc\u00ea sentiu profundamente que Deus estava falando com voc\u00ea. O que aconteceu? Como se sentiu?"}'), ('c1c2c3d4-3305-4000-8000-000000000005', 'b1b2c3d4-3333-4000-8000-000000000003', 5, 'Modelos de Vocação', 'Santos que discerniram', '{"text": "Grandes santos passaram por intensos processos de discernimento:\n\n**Santo Agostinho** \u2014 Lutou anos entre a vida mundana e o chamado divino at\u00e9 sua convers\u00e3o no jardim de Mil\u00e3o: \"Tarde te amei, \u00f3 Beleza t\u00e3o antiga e t\u00e3o nova!\"\n\n**Santa Teresa de Lisieux** \u2014 Desde crian\u00e7a sentiu o chamado ao Carmelo, mas precisou superar obst\u00e1culos e esperar o tempo de Deus.\n\n**S\u00e3o Francisco de Assis** \u2014 Filho de comerciante rico, ouviu Cristo dizer: \"Francisco, vai e repara minha Igreja.\" Abandonou tudo.\n\n**Santa Madre Teresa de Calcut\u00e1** \u2014 J\u00e1 religiosa, recebeu um \"chamado dentro do chamado\" para servir os mais pobres dos pobres.\n\nCada voca\u00e7\u00e3o \u00e9 \u00fanica. Deus n\u00e3o se repete.", "scripture": "Ef 2,10 \u2014 Somos obra de Deus, criados em Cristo Jesus para as boas obras que Deus de antem\u00e3o preparou para que nelas and\u00e1ssemos."}'), ('c1c2c3d4-3306-4000-8000-000000000006', 'b1b2c3d4-3333-4000-8000-000000000003', 6, 'Quiz: Discernimento', 'Teste seus conhecimentos', '{"questions": [{"q": "Segundo Santo In\u00e1cio, o que N\u00c3O se deve fazer em tempo de desola\u00e7\u00e3o?", "correct": 1, "options": ["Rezar mais", "Fazer mudan\u00e7as importantes", "Buscar dire\u00e7\u00e3o espiritual", "Jejuar"]}, {"q": "Qual \u00e9 o primeiro passo do discernimento vocacional?", "correct": 1, "options": ["Pesquisar semin\u00e1rios", "Dispor-se a ouvir a vontade de Deus", "Consultar amigos", "Fazer um retiro"]}, {"q": "Quantas voca\u00e7\u00f5es fundamentais a Igreja reconhece?", "correct": 2, "options": ["2", "3", "4", "5"]}]}'), ('d1d2d3d4-4401-4000-8000-000000000001', 'b1b2c3d4-4444-4000-8000-000000000004', 1, 'O Corpo Revela a Pessoa', 'Introdução à Teologia do Corpo', '{"text": "S\u00e3o Jo\u00e3o Paulo II dedicou 129 audi\u00eancias (1979\u20131984) a desenvolver uma vis\u00e3o revolucion\u00e1ria: o corpo humano n\u00e3o \u00e9 apenas mat\u00e9ria \u2014 \u00e9 uma teologia viva, uma linguagem que revela o mist\u00e9rio de Deus.\n\n**\"O corpo, e somente ele, \u00e9 capaz de tornar vis\u00edvel o que \u00e9 invis\u00edvel: o espiritual e o divino.\"** \u2014 S\u00e3o Jo\u00e3o Paulo II\n\nNo relato da cria\u00e7\u00e3o (Gn 1-2), encontramos tr\u00eas experi\u00eancias origin\u00e1rias:\n\n1. **Solid\u00e3o Original** \u2014 Ad\u00e3o percebe que \u00e9 diferente dos animais; possui autoconsci\u00eancia e liberdade.\n2. **Unidade Original** \u2014 \"Ser\u00e3o os dois uma s\u00f3 carne\" (Gn 2,24). O corpo foi feito para a comunh\u00e3o.\n3. **Nudez Original** \u2014 \"Estavam nus e n\u00e3o sentiam vergonha\" (Gn 2,25). A pureza do olhar antes do pecado.\n\nA Teologia do Corpo n\u00e3o \u00e9 apenas sobre sexualidade \u2014 \u00e9 sobre o significado de ser pessoa.", "scripture": "Gn 1,27 \u2014 Deus criou o ser humano \u00e0 sua imagem; \u00e0 imagem de Deus o criou; homem e mulher os criou."}'), ('d1d2d3d4-4402-4000-8000-000000000002', 'b1b2c3d4-4444-4000-8000-000000000004', 2, 'Oração: Contemplar o Dom', 'Agradecer pelo corpo como dom', '{"text": "Senhor Deus,\nV\u00f3s me criastes \u00e0 Vossa imagem e semelhan\u00e7a.\nMeu corpo \u00e9 templo do Esp\u00edrito Santo,\nlinguagem viva do Vosso amor.\n\nAjudai-me a contemplar meu corpo\nn\u00e3o como objeto de vergonha ou idolatria,\nmas como dom sagrado que revela\no mist\u00e9rio da comunh\u00e3o e da entrega.\n\nPurificai meu olhar,\npara que eu veja em cada pessoa\na dignidade inviol\u00e1vel de filho de Deus.\n\nS\u00e3o Jo\u00e3o Paulo II, rogai por n\u00f3s.\nAm\u00e9m.", "instruction": "Reze diante de um crucifixo, contemplando como Cristo entregou Seu corpo por amor."}'), ('d1d2d3d4-4403-4000-8000-000000000003', 'b1b2c3d4-4444-4000-8000-000000000004', 3, 'O Significado Esponsal', 'O corpo como dom e entrega', '{"text": "O conceito central da Teologia do Corpo \u00e9 o **significado esponsal do corpo**: a capacidade de expressar amor como doa\u00e7\u00e3o total de si.\n\n**\"O homem n\u00e3o pode viver sem amor. Ele permanece para si mesmo um ser incompreens\u00edvel se o amor n\u00e3o lhe for revelado.\"** \u2014 Redemptor Hominis, 10\n\nO corpo revela que fomos feitos para:\n- **Dar-nos** \u2014 o amor aut\u00eantico \u00e9 sempre dom de si\n- **Receber** \u2014 aceitar o dom do outro com rever\u00eancia\n- **Ser fecundos** \u2014 o amor gera vida, seja biol\u00f3gica ou espiritual\n\nO pecado original distorceu esta linguagem:\n- A **concupisc\u00eancia** reduz a pessoa a objeto\n- A **vergonha** indica a perda da inoc\u00eancia original\n- O **dom\u00ednio** substitui a comunh\u00e3o\n\nMas Cristo veio restaurar o plano original. Na cruz, Ele mostra o significado esponsal em sua plenitude: entrega total, livre, fiel e fecunda.", "scripture": "Ef 5,25 \u2014 Maridos, amai vossas esposas, como Cristo amou a Igreja e se entregou por ela."}'), ('d1d2d3d4-4404-4000-8000-000000000004', 'b1b2c3d4-4444-4000-8000-000000000004', 4, 'Reflexão: Meu Corpo como Linguagem', 'Integrar corpo e espírito', '{"text": "S\u00e3o Jo\u00e3o Paulo II nos convida a uma revolu\u00e7\u00e3o interior: ver o corpo como linguagem do amor.\n\nReflita:\n1. **Como eu trato meu corpo?** Com respeito ou neglig\u00eancia?\n2. **Como eu olho para o corpo dos outros?** Com rever\u00eancia ou objetifica\u00e7\u00e3o?\n3. **Minha cultura me ajuda ou atrapalha** a viver a verdade do corpo?\n4. **Em que \u00e1reas da minha vida** preciso de purifica\u00e7\u00e3o do olhar?\n5. **Como posso viver a castidade** como afirma\u00e7\u00e3o do amor, n\u00e3o como repress\u00e3o?\n\nA castidade n\u00e3o \u00e9 dizer \"n\u00e3o\" ao corpo \u2014 \u00e9 dizer \"sim\" ao amor verdadeiro.", "prompt": "Escreva sobre como a cultura atual influencia sua vis\u00e3o do corpo e da sexualidade. Como a Teologia do Corpo pode transformar esse olhar?"}'), ('d1d2d3d4-4405-4000-8000-000000000005', 'b1b2c3d4-4444-4000-8000-000000000004', 5, 'A Ressurreição do Corpo', 'Esperança escatológica', '{"text": "A Teologia do Corpo n\u00e3o termina na morte \u2014 aponta para a ressurrei\u00e7\u00e3o.\n\nQuando os saduceus perguntaram a Jesus sobre o casamento na ressurrei\u00e7\u00e3o, Ele respondeu: \"Na ressurrei\u00e7\u00e3o, nem se casam nem se d\u00e3o em casamento, mas s\u00e3o como anjos no c\u00e9u\" (Mt 22,30).\n\nS\u00e3o Jo\u00e3o Paulo II interpreta: na ressurrei\u00e7\u00e3o, o significado esponsal do corpo ser\u00e1 plenamente realizado \u2014 n\u00e3o no matrim\u00f4nio terreno, mas na **comunh\u00e3o perfeita com Deus**.\n\n**O que isso significa para n\u00f3s agora?**\n- O celibato/virgindade consagrada \u00e9 um sinal antecipado da vida futura\n- O matrim\u00f4nio \u00e9 sacramento que aponta para a uni\u00e3o Cristo-Igreja\n- Toda voca\u00e7\u00e3o \u00e9 chamado ao amor que transcende a morte\n\n\"O corpo glorioso ser\u00e1 a revela\u00e7\u00e3o definitiva da beleza de Deus.\"", "scripture": "1Cor 15,44 \u2014 Semeia-se corpo animal, ressuscita corpo espiritual."}'), ('d1d2d3d4-4406-4000-8000-000000000006', 'b1b2c3d4-4444-4000-8000-000000000004', 6, 'Quiz: Teologia do Corpo', 'Teste seus conhecimentos', '{"questions": [{"q": "Quantas audi\u00eancias S\u00e3o Jo\u00e3o Paulo II dedicou \u00e0 Teologia do Corpo?", "correct": 2, "options": ["50", "89", "129", "200"]}, {"q": "Qual \u00e9 o conceito central da Teologia do Corpo?", "correct": 1, "options": ["A proibi\u00e7\u00e3o do prazer", "O significado esponsal do corpo", "A superioridade da alma", "A rejei\u00e7\u00e3o da mat\u00e9ria"]}, {"q": "O que a ''nudez original'' (Gn 2,25) significa teologicamente?", "correct": 1, "options": ["Pobreza material", "Pureza do olhar antes do pecado", "Aus\u00eancia de roupas", "Ingenuidade"]}]}'), ('d96679a4-1535-4692-8929-03959d5fe1c9', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 1, 'O Deserto Interior', NULL, '{"intro": "A m\u00edstica come\u00e7a no sil\u00eancio radical da alma.", "prayer": "Fique 15 minutos em adora\u00e7\u00e3o silenciosa.", "practice": "Desligue as notifica\u00e7\u00f5es do celular por 2 horas.", "reflection": "Onde n\u00e3o h\u00e1 barulho, o Absoluto fala.", "journal_prompt": "Por que voc\u00ea tem medo do sil\u00eancio?"}'), ('7503cfc8-39a8-4c1b-95ba-b98825aa22dd', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 2, 'A Pobreza de Espírito', NULL, '{"intro": "O apego \u00e0s coisas \u00e9 o peso que impede o voo da alma.", "prayer": "Repita: Eu n\u00e3o sou nada, Tu \u00e9s tudo.", "practice": "Doe algo que voc\u00ea gosta para algu\u00e9m que precise.", "reflection": "S\u00f3 quem nada possui pode possuir Tudo.", "journal_prompt": "O que voc\u00ea ainda tenta segurar com as m\u00e3os fechadas?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;